      {"id":"i_ts_overflow","name":"Tube settler: Sludge overflow / carryover over outlet weir","sheet":"MBBR Issues","from":"MBBR","rows":[103,111],"homeTypes":["Tube settler"],"detection":[{"kind":"visual","text":"Visual inspection: floc / sludge particles over the weir and in the outlet channel; sludge on top of tubes","task":"t_mb_scum","tasks":["t_mb_scum"],"why":"the daily scum removal looks at the settler surface"},{"kind":"sensor","text":"Sensor: outlet turbidity / TSS sensor, sludge blanket level detector","readings":[{"name":"Outlet turbidity","where":"connection"},{"name":"Sludge blanket","where":"equipment"}],"alert":"Sludge blanket high","alerts":["Sludge blanket high"],"why":"the tube settler's Sludge blanket high alert opens this issue; outlet turbidity is a connection","alertsByType":{"Tube settler":["Sludge blanket high"]}},{"kind":"manual","text":"Manual testing: TSS (lab), Imhoff cone; sludge blanket depth with a sludge judge","task":"t_mb_tss","tasks":["t_mb_tss"],"why":"the TSS test"}],"causes":["c_ts_overflow_1","c_ts_overflow_2","c_ts_overflow_3","c_ts_overflow_4","c_ts_overflow_5","c_ts_overflow_6","c_ts_overflow_7","c_ts_overflow_8","c_ts_overflow_9"],"flow":"d_ts_overflow","source":{"sheet":"MBBR Issues","row":103}},
      {"id":"i_ts_line","name":"Tube settler: Choked / blocked sludge withdrawal line","sheet":"MBBR Issues","from":"MBBR","rows":[112,118],"homeTypes":["Tube settler"],"detection":[{"kind":"visual","text":"Visual inspection: no or very little sludge coming out during desludging, sludge blanket rising","task":"t_mb_desludge","tasks":["t_mb_desludge"],"why":"desludging watches the sludge come out"},{"kind":"sensor","text":"Sensor: sludge pump low flow / high discharge pressure / high or no-load current; flow meter on sludge line","readings":[{"name":"Flow","where":"connection"},{"name":"Discharge pressure","where":"connection"},{"name":"Motor current","where":"equipment","on":["Pump","Submersible Pump"]}],"why":"flow and pressure are on the sludge line (next phase); the current is on the sludge pump"}],"causes":["c_ts_line_1","c_ts_line_2","c_ts_line_3","c_ts_line_4","c_ts_line_5","c_ts_line_6","c_ts_line_7"],"flow":"d_ts_line","source":{"sheet":"MBBR Issues","row":112}},
      {"id":"i_ts_yellow","name":"Tube settler: Yellowish water at tube settler outlet","sheet":"MBBR Issues","from":"MBBR","rows":[119,124],"homeTypes":["Tube settler"],"detection":[{"kind":"visual","text":"Visual inspection: yellow / brownish tint in clarified water (often clear but coloured)","task":"t_mb_colour","tasks":["t_mb_colour"],"why":"the colour and odour check"},{"kind":"manual","text":"Manual testing: colour (Pt-Co / Hazen units) by colour kit or spectrophotometer","why":"no task measures colour in Hazen units"}],"causes":["c_ts_yellow_1","c_ts_yellow_2","c_ts_yellow_3","c_ts_yellow_4","c_ts_yellow_5","c_ts_yellow_6"],"flow":"d_ts_yellow","source":{"sheet":"MBBR Issues","row":119}},
      {"id":"i_ts_media","name":"Tube settler: Tube media choked / algae growth / sludge deposits on tubes","sheet":"MBBR Issues","from":"MBBR","rows":[125,128],"homeTypes":["Tube settler"],"detection":[{"kind":"visual","text":"Visual inspection: sludge or green algae on top of and inside tube modules, sagging tubes, uneven surface flow","task":"t_mb_ts_inspect","tasks":["t_mb_ts_inspect"],"why":"the tube module inspection"}],"causes":["c_ts_media_1","c_ts_media_2","c_ts_media_3","c_ts_media_4"],"flow":"d_ts_media","source":{"sheet":"MBBR Issues","row":125}},
      {"id":"i_ts_scum","name":"Tube settler: Floating scum / sludge mat on surface","sheet":"MBBR Issues","from":"MBBR","rows":[129,131],"homeTypes":["Tube settler"],"detection":[{"kind":"visual","text":"Visual inspection: floating sludge, grease or scum on settler surface","task":"t_mb_scum","tasks":["t_mb_scum"],"why":"the scum removal from the settler surface"}],"causes":["c_ts_scum_1","c_ts_scum_2","c_ts_scum_3"],"flow":"d_ts_scum","source":{"sheet":"MBBR Issues","row":129}},
      {"id":"i_ts_pump","name":"Tube settler: Breakdown of sludge recirculation / sludge wasting pump","sheet":"MBBR Issues","from":"MBBR","rows":[132,146],"homeTypes":["Pump","Submersible Pump","Tube settler"],"detection":[{"kind":"sensor","text":"Sensor: pump trip / fault alarm in MCC or SCADA, motor current sensor (zero, very high or very low current), flow meter on sludge line showing no/low flow, discharge pressure gauge, moisture / thermal sensor alarm (submersible pumps)","readings":[{"name":"Trip contact","where":"equipment","on":["Pump","Submersible Pump"]},{"name":"Motor current","where":"equipment","on":["Pump","Submersible Pump"]},{"name":"Flow","where":"connection"},{"name":"Discharge pressure","where":"connection"},{"name":"Seal moisture","where":"equipment","on":["Pump","Submersible Pump"]},{"name":"Winding temperature","where":"equipment","on":["Pump","Submersible Pump"]}],"why":"trip, current, moisture and winding temperature are on the pump (Pump, Submersible Pump), not on the Tube settler; flow and pressure are on the sludge line (next phase). The pump's current alert is shared by every pump, so it keeps its own diagnostic"},{"kind":"visual","text":"Visual inspection: pump not running or running without sludge discharge, abnormal noise/vibration, leakage at seal, sludge blanket rising in tube settler","task":"t_mb_sludge_pump_check","tasks":["t_mb_sludge_pump_check"],"why":"the sludge pump and sludge line check"},{"kind":"manual","text":"Manual testing: sludge blanket depth with sludge judge","why":"no task measures the blanket with a sludge judge"}],"causes":["c_ts_pump_1","c_ts_pump_2","c_ts_pump_3","c_ts_pump_4","c_ts_pump_5","c_ts_pump_6","c_ts_pump_7","c_ts_pump_8","c_ts_pump_9","c_ts_pump_10","c_ts_pump_11","c_ts_pump_12","c_ts_pump_13","c_ts_pump_14","c_ts_pump_15"],"flow":"d_ts_pump","source":{"sheet":"MBBR Issues","row":132}}
