      {"id":"f_fix_ts_bulking_3","name":"Fix: Low F/M (under-loaded plant) or high F/M organic overload.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Balance organic loading through the equalisation tank and adjust operating reactors to match load."}],"cause":"c_ts_bulking_3","issue":"i_ts_bulking","source":{"sheet":"MBBR Issues","row":97}},
      {"id":"f_fix_ts_bulking_4","name":"Fix: Septic influent with sulphides / high volatile fatty acids (favours Thiothrix, Beggiatoa).","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Pre-aerate the influent, reduce retention in upstream sumps and trace septic discharge."}],"cause":"c_ts_bulking_4","issue":"i_ts_bulking","source":{"sheet":"MBBR Issues","row":98}},
      {"id":"f_fix_ts_bulking_5","name":"Fix: High fat, oil & grease favouring Nocardia / Microthrix.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Improve oil & grease removal upstream and remove scum from tube settler surface.","link":{"kind":"task","id":"t_mb_scum"}}],"cause":"c_ts_bulking_5","issue":"i_ts_bulking","source":{"sheet":"MBBR Issues","row":99}},
      {"id":"f_fix_ts_bulking_6","name":"Fix: Low pH (< 6.5).","kind":"action","forTypes":["Tube settler","Dosing Pump","Dosing Tank"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Dose alkali to bring pH to 7.0-8.0."}],"cause":"c_ts_bulking_6","issue":"i_ts_bulking","source":{"sheet":"MBBR Issues","row":100}},
      {"id":"f_fix_ts_bulking_7","name":"Fix: Viscous (non-filamentous) bulking from slime-forming bacteria due to nutrient deficiency or high readily-biodegradable load (sugars, food waste).","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Correct nutrient deficiency and equalise high-strength load."}],"cause":"c_ts_bulking_7","issue":"i_ts_bulking","source":{"sheet":"MBBR Issues","row":101}},
      {"id":"f_fix_ts_bulking_8","name":"Fix: Sludge held too long in settler and rising by denitrification (looks like bulking: sludge clumps with gas bubbles).","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Increase sludge withdrawal frequency.","link":{"kind":"task","id":"t_mb_desludge"}}],"cause":"c_ts_bulking_8","issue":"i_ts_bulking","source":{"sheet":"MBBR Issues","row":102}},
      {"id":"f_fix_ts_overflow_1","name":"Fix: Sludge not withdrawn regularly, so the sludge blanket rises into the tubes and over the weir.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Desludge immediately and set a fixed sludge withdrawal schedule (based on sludge blanket depth).","link":{"kind":"task","id":"t_mb_desludge"}},{"id":2,"type":"instruction","text":"Keep the blanket well below the tube media."}],"cause":"c_ts_overflow_1","issue":"i_ts_overflow","source":{"sheet":"MBBR Issues","row":103}},
      {"id":"f_fix_ts_overflow_2","name":"Fix: Choked sludge withdrawal line / sludge pump failure.","kind":"action","forTypes":["Tube settler","Pump","Submersible Pump"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Clear the line and repair the pump (see 'Choked sludge line').","link":{"kind":"issue","id":"i_ts_line"}}],"cause":"c_ts_overflow_2","issue":"i_ts_overflow","source":{"sheet":"MBBR Issues","row":104}},
      {"id":"f_fix_ts_overflow_3","name":"Fix: Hydraulic overload: flow above design surface overflow rate of the tube settler.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Reduce/equalise the feed flow."},{"id":2,"type":"instruction","text":"Check design surface loading against actual peak flow and add settling area if needed."}],"cause":"c_ts_overflow_3","issue":"i_ts_overflow","source":{"sheet":"MBBR Issues","row":105}},
      {"id":"f_fix_ts_overflow_4","name":"Fix: High solids load from MBBR (biofilm sloughing, high SV-30).","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Find the cause of sloughing and dose coagulant/polymer to improve settling (see 'High SV-30').","link":{"kind":"issue","id":"i_mb_sv30"}}],"cause":"c_ts_overflow_4","issue":"i_ts_overflow","source":{"sheet":"MBBR Issues","row":106}},
      {"id":"f_fix_ts_overflow_5","name":"Fix: Sludge bulking (poor settling sludge).","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"See 'Sludge bulking in tube settler'.","link":{"kind":"issue","id":"i_ts_bulking"}}],"cause":"c_ts_overflow_5","issue":"i_ts_overflow","source":{"sheet":"MBBR Issues","row":107}},
      {"id":"f_fix_ts_overflow_6","name":"Fix: Rising sludge due to denitrification (gas bubbles lifting sludge) or septic sludge.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Increase desludging frequency and reduce sludge retention.","link":{"kind":"task","id":"t_mb_desludge"}}],"cause":"c_ts_overflow_6","issue":"i_ts_overflow","source":{"sheet":"MBBR Issues","row":108}},
      {"id":"f_fix_ts_overflow_7","name":"Fix: Tube media choked, so flow takes short-cuts through the open tubes at high velocity.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Clean the tube media with water jet / air scour.","link":{"kind":"task","id":"t_mb_ts_media"}},{"id":2,"type":"instruction","text":"Replace damaged modules."}],"cause":"c_ts_overflow_7","issue":"i_ts_overflow","source":{"sheet":"MBBR Issues","row":109}},
      {"id":"f_fix_ts_overflow_8","name":"Fix: Outlet weir not level / V-notches blocked, causing uneven draw-off and short-circuiting.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Level the weir plates and clean V-notches and launders.","link":{"kind":"task","id":"t_mb_launder"}}],"cause":"c_ts_overflow_8","issue":"i_ts_overflow","source":{"sheet":"MBBR Issues","row":110}},
      {"id":"f_fix_ts_overflow_9","name":"Fix: Inlet baffle / stilling well damaged, so incoming flow disturbs the sludge zone.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Repair/replace the inlet baffle and check inlet velocity."}],"cause":"c_ts_overflow_9","issue":"i_ts_overflow","source":{"sheet":"MBBR Issues","row":111}},
      {"id":"f_fix_ts_line_1","name":"Fix: Sludge compacted and thickened in the hopper due to infrequent withdrawal.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Withdraw sludge more frequently in short bursts.","link":{"kind":"task","id":"t_mb_desludge"}},{"id":2,"type":"instruction","text":"Flush the line with water / compressed air after each withdrawal."}],"cause":"c_ts_line_1","issue":"i_ts_line","source":{"sheet":"MBBR Issues","row":112}},
      {"id":"f_fix_ts_line_2","name":"Fix: Rags, plastics or fibres (poor screening) blocking the line or valve.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Rod or back-flush the line through rodding points."},{"id":2,"type":"instruction","text":"Improve upstream screening."}],"cause":"c_ts_line_2","issue":"i_ts_line","source":{"sheet":"MBBR Issues","row":113}},
      {"id":"f_fix_ts_line_3","name":"Fix: Grit / sand settled in the line.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Flush the line with high-pressure water."},{"id":2,"type":"instruction","text":"Improve grit removal upstream."}],"cause":"c_ts_line_3","issue":"i_ts_line","source":{"sheet":"MBBR Issues","row":114}},
      {"id":"f_fix_ts_line_4","name":"Fix: Sludge valve stuck / not fully opening (not operated for long, corrosion).","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Exercise valves regularly, lubricate and replace stuck valves.","link":{"kind":"task","id":"t_mb_sludge_valves"}}],"cause":"c_ts_line_4","issue":"i_ts_line","source":{"sheet":"MBBR Issues","row":115}},
      {"id":"f_fix_ts_line_5","name":"Fix: Sludge pump problem: impeller clogged or worn, air-lock, motor fault; for airlift pumps low air supply.","kind":"action","forTypes":["Tube settler","Pump","Submersible Pump"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Clean impeller, vent air, check motor.","link":{"kind":"task","id":"t_mb_pump_pm"}},{"id":2,"type":"instruction","text":"For airlift pumps clean the air nozzle and check air supply."}],"cause":"c_ts_line_5","issue":"i_ts_line","source":{"sheet":"MBBR Issues","row":116}},
      {"id":"f_fix_ts_line_6","name":"Fix: Line design: small diameter (< 100-150 mm), long horizontal run or no flushing / rodding points.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Provide flushing connections and rodding points."},{"id":2,"type":"instruction","text":"Increase pipe size during modification."}],"cause":"c_ts_line_6","issue":"i_ts_line","source":{"sheet":"MBBR Issues","row":117}},
      {"id":"f_fix_ts_line_7","name":"Fix: Hopper slope too flat, so sludge sticks and bridges above the outlet.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Agitate/flush the hopper with water or air lance during desludging.","link":{"kind":"task","id":"t_mb_desludge"}},{"id":2,"type":"instruction","text":"Review hopper slope (≥ 55-60°) in design."}],"cause":"c_ts_line_7","issue":"i_ts_line","source":{"sheet":"MBBR Issues","row":118}},
      {"id":"f_fix_ts_yellow_1","name":"Fix: Incomplete biological treatment - soluble organics remaining (high soluble COD).","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Check effluent COD/BOD and correct the cause (low DO, overload, toxicity - see 'High effluent BOD / COD').","link":{"kind":"task","id":"t_mb_cod"},"links":[{"kind":"task","id":"t_mb_cod"},{"kind":"task","id":"t_mb_bod"},{"kind":"issue","id":"i_mb_bod"}]}],"cause":"c_ts_yellow_1","issue":"i_ts_yellow","source":{"sheet":"MBBR Issues","row":119}},
      {"id":"f_fix_ts_yellow_2","name":"Fix: Septic sludge in tube settler hopper releasing coloured, soluble decomposition products.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Increase desludging frequency and clean deposits from tubes and corners.","link":{"kind":"task","id":"t_mb_desludge"},"links":[{"kind":"task","id":"t_mb_desludge"},{"kind":"task","id":"t_mb_ts_media"}]}],"cause":"c_ts_yellow_2","issue":"i_ts_yellow","source":{"sheet":"MBBR Issues","row":120}},
      {"id":"f_fix_ts_yellow_3","name":"Fix: Fine colloidal biomass / pin floc not settling (dispersed growth after shock or sloughing).","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Dose coagulant and polymer before the settler."},{"id":2,"type":"instruction","text":"Remove the shock cause."}],"cause":"c_ts_yellow_3","issue":"i_ts_yellow","source":{"sheet":"MBBR Issues","row":121}},
      {"id":"f_fix_ts_yellow_4","name":"Fix: Ferric-based coagulant (ferric chloride / ferrous sulphate) overdosed for phosphorous removal, leaving residual iron that colours water yellow-brown.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Optimise dose with jar test and check pH (iron coagulants work best at pH 6-8)."},{"id":2,"type":"instruction","text":"Test residual iron."}],"cause":"c_ts_yellow_4","issue":"i_ts_yellow","source":{"sheet":"MBBR Issues","row":122}},
      {"id":"f_fix_ts_yellow_5","name":"Fix: Algae growth on tube media / settler walls (sunlight) - yellow-green tint.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Clean tubes and walls regularly.","link":{"kind":"task","id":"t_mb_ts_media"},"links":[{"kind":"task","id":"t_mb_ts_media"},{"kind":"task","id":"t_mb_algae"}]},{"id":2,"type":"instruction","text":"Cover the settler / provide shading."}],"cause":"c_ts_yellow_5","issue":"i_ts_yellow","source":{"sheet":"MBBR Issues","row":123}},
      {"id":"f_fix_ts_yellow_6","name":"Fix: Nitrite build-up from incomplete nitrification (can give slight yellow tint with some reagents/ chlorine demand).","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Test nitrite.","link":{"kind":"task","id":"t_mb_nitrate"}},{"id":2,"type":"instruction","text":"Improve DO and alkalinity for complete nitrification."}],"cause":"c_ts_yellow_6","issue":"i_ts_yellow","source":{"sheet":"MBBR Issues","row":124}},
      {"id":"f_fix_ts_media_1","name":"Fix: Sludge settling on and inside tubes not sliding down (infrequent cleaning, sticky sludge).","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Clean tubes with a water jet from the top or air scouring from below.","link":{"kind":"task","id":"t_mb_ts_media"}},{"id":2,"type":"instruction","text":"Lower water level and clean periodically (e.g. monthly).","link":{"kind":"task","id":"t_mb_ts_media"}}],"cause":"c_ts_media_1","issue":"i_ts_media","source":{"sheet":"MBBR Issues","row":125}},
      {"id":"f_fix_ts_media_2","name":"Fix: Algae growth from sunlight exposure.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Provide cover / shading and clean regularly.","link":{"kind":"task","id":"t_mb_ts_media"},"links":[{"kind":"task","id":"t_mb_ts_media"},{"kind":"task","id":"t_mb_algae"}]}],"cause":"c_ts_media_2","issue":"i_ts_media","source":{"sheet":"MBBR Issues","row":126}},
      {"id":"f_fix_ts_media_3","name":"Fix: Sludge blanket allowed to rise into the tubes.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Increase desludging frequency.","link":{"kind":"task","id":"t_mb_desludge"}}],"cause":"c_ts_media_3","issue":"i_ts_media","source":{"sheet":"MBBR Issues","row":127}},
      {"id":"f_fix_ts_media_4","name":"Fix: Tube modules damaged / sagging due to weight of sludge or degradation, or inadequate support.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Replace damaged modules with UV-stabilised PVC/PP tubes."},{"id":2,"type":"instruction","text":"Repair supporting frame."}],"cause":"c_ts_media_4","issue":"i_ts_media","source":{"sheet":"MBBR Issues","row":128}},
      {"id":"f_fix_ts_scum_1","name":"Fix: Rising sludge due to denitrification or septic sludge in hopper.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Increase desludging frequency.","link":{"kind":"task","id":"t_mb_desludge"}}],"cause":"c_ts_scum_1","issue":"i_ts_scum","source":{"sheet":"MBBR Issues","row":129}},
      {"id":"f_fix_ts_scum_2","name":"Fix: Oil, grease and foam carried over from MBBR.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Improve oil & grease removal upstream, remove scum manually and provide a scum baffle at outlet.","link":{"kind":"task","id":"t_mb_scum"}}],"cause":"c_ts_scum_2","issue":"i_ts_scum","source":{"sheet":"MBBR Issues","row":130}},
      {"id":"f_fix_ts_scum_3","name":"Fix: Filamentous bacteria (Nocardia / Microthrix) scum.","kind":"action","forTypes":["Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Remove scum from system (do not return it to MBBR).","link":{"kind":"task","id":"t_mb_scum"}},{"id":2,"type":"instruction","text":"Control FOG and check DO / nutrients."}],"cause":"c_ts_scum_3","issue":"i_ts_scum","source":{"sheet":"MBBR Issues","row":131}},
      {"id":"f_fix_ts_pump_1","name":"Fix: Impeller clogged with rags, fibres or plastics (poor upstream screening).","kind":"action","forTypes":["Pump","Submersible Pump","Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Switch to standby pump.","link":{"kind":"task","id":"t_mb_pump_changeover"}},{"id":2,"type":"instruction","text":"Apply LOTO, open the pump and clean the impeller.","link":{"kind":"task","id":"t_mb_pump_pm"}},{"id":3,"type":"instruction","text":"Use non-clog / vortex / cutter impeller and improve fine screening upstream."}],"cause":"c_ts_pump_1","issue":"i_ts_pump","source":{"sheet":"MBBR Issues","row":132}},
      {"id":"f_fix_ts_pump_2","name":"Fix: Pump running dry or suction starved: low sludge level in hopper/sump, choked suction line, air lock.","kind":"action","forTypes":["Pump","Submersible Pump","Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Clear the suction line, vent air and prime the pump."},{"id":2,"type":"instruction","text":"Provide low-level / dry-run protection interlock."}],"cause":"c_ts_pump_2","issue":"i_ts_pump","source":{"sheet":"MBBR Issues","row":133}},
      {"id":"f_fix_ts_pump_3","name":"Fix: Motor overload trip due to very thick sludge, choked discharge line or closed discharge valve.","kind":"action","forTypes":["Pump","Submersible Pump","Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Find and remove the cause before resetting the overload."},{"id":2,"type":"instruction","text":"Withdraw sludge more frequently so it does not get too thick.","link":{"kind":"task","id":"t_mb_desludge"}},{"id":3,"type":"instruction","text":"Check the overload setting against the motor nameplate."}],"cause":"c_ts_pump_3","issue":"i_ts_pump","source":{"sheet":"MBBR Issues","row":134}},
      {"id":"f_fix_ts_pump_4","name":"Fix: Discharge valve closed, non-return valve stuck, or discharge line choked.","kind":"action","forTypes":["Pump","Submersible Pump","Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Open the valve, free or replace the NRV and flush/rod the discharge line."}],"cause":"c_ts_pump_4","issue":"i_ts_pump","source":{"sheet":"MBBR Issues","row":135}},
      {"id":"f_fix_ts_pump_5","name":"Fix: Electrical fault: single phasing, voltage fluctuation, burnt winding, failed contactor/starter, damaged cable (submersible).","kind":"action","forTypes":["Pump","Submersible Pump","Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Check supply on all phases, starter and terminations."},{"id":2,"type":"instruction","text":"Megger-test the motor and cable.","link":{"kind":"task","id":"t_mb_megger"}},{"id":3,"type":"instruction","text":"Repair/rewind or replace."},{"id":4,"type":"instruction","text":"Install phase-failure and under/over-voltage protection."}],"cause":"c_ts_pump_5","issue":"i_ts_pump","source":{"sheet":"MBBR Issues","row":136}},
      {"id":"f_fix_ts_pump_6","name":"Fix: Mechanical seal / gland failure causing leakage; water entering submersible motor (moisture sensor trip).","kind":"action","forTypes":["Pump","Submersible Pump","Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Replace the mechanical seal / gland packing.","link":{"kind":"task","id":"t_mb_pump_pm"}},{"id":2,"type":"instruction","text":"For submersible pumps check the oil chamber, replace seals and dry/repair the motor."}],"cause":"c_ts_pump_6","issue":"i_ts_pump","source":{"sheet":"MBBR Issues","row":137}},
      {"id":"f_fix_ts_pump_7","name":"Fix: Bearing failure (lack of lubrication, misalignment, vibration).","kind":"action","forTypes":["Pump","Submersible Pump","Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Replace bearings, check alignment and follow the lubrication schedule.","link":{"kind":"task","id":"t_mb_pump_pm"}},{"id":2,"type":"instruction","text":"Monitor vibration and temperature."}],"cause":"c_ts_pump_7","issue":"i_ts_pump","source":{"sheet":"MBBR Issues","row":138}},
      {"id":"f_fix_ts_pump_8","name":"Fix: Coupling damaged or pump-motor misaligned, causing vibration and breakdown.","kind":"action","forTypes":["Pump","Submersible Pump","Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Realign the pump and motor and replace damaged coupling elements.","link":{"kind":"task","id":"t_mb_pump_pm"}}],"cause":"c_ts_pump_8","issue":"i_ts_pump","source":{"sheet":"MBBR Issues","row":139}},
      {"id":"f_fix_ts_pump_9","name":"Fix: Impeller / casing worn by grit abrasion, so pump runs but delivers little sludge.","kind":"action","forTypes":["Pump","Submersible Pump","Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Replace the impeller, wear ring or casing."},{"id":2,"type":"instruction","text":"Improve grit removal upstream and consider abrasion-resistant materials."}],"cause":"c_ts_pump_9","issue":"i_ts_pump","source":{"sheet":"MBBR Issues","row":140}},
      {"id":"f_fix_ts_pump_10","name":"Fix: Progressive cavity (screw) pump: stator burnt or worn from dry running, rotor worn.","kind":"action","forTypes":["Pump","Submersible Pump","Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Replace stator/rotor."},{"id":2,"type":"instruction","text":"Install dry-run protection (stator thermal sensor or flow switch)."}],"cause":"c_ts_pump_10","issue":"i_ts_pump","source":{"sheet":"MBBR Issues","row":141}},
      {"id":"f_fix_ts_pump_11","name":"Fix: Airlift sludge pump: low air supply, air valve closed or air nozzle choked.","kind":"action","forTypes":["Pump","Submersible Pump","Tube settler","Blower"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Check the air valve and blower supply, clean the air nozzle and riser pipe."}],"cause":"c_ts_pump_11","issue":"i_ts_pump","source":{"sheet":"MBBR Issues","row":142}},
      {"id":"f_fix_ts_pump_12","name":"Fix: Control fault: timer, level float or PLC/VFD not giving start signal, or pump left in OFF/manual mode.","kind":"action","forTypes":["Pump","Submersible Pump","Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Check the timer, float and VFD/PLC signals and set the pump to AUTO."},{"id":2,"type":"instruction","text":"Run in manual until repaired."}],"cause":"c_ts_pump_12","issue":"i_ts_pump","source":{"sheet":"MBBR Issues","row":143}},
      {"id":"f_fix_ts_pump_13","name":"Fix: Standby pump not available or not maintained, so a single breakdown stops desludging.","kind":"action","forTypes":["Pump","Submersible Pump","Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Keep the standby pump healthy, rotate duty/standby weekly and set auto-changeover on duty pump failure.","link":{"kind":"task","id":"t_mb_pump_changeover"}}],"cause":"c_ts_pump_13","issue":"i_ts_pump","source":{"sheet":"MBBR Issues","row":144}},
      {"id":"f_fix_ts_pump_14","name":"Fix: No preventive maintenance (inspection, lubrication, seal check) as per OEM schedule.","kind":"action","forTypes":["Pump","Submersible Pump","Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Set a preventive maintenance schedule and keep critical spares (seals, bearings, impeller, stator).","link":{"kind":"task","id":"t_mb_pump_pm"}}],"cause":"c_ts_pump_14","issue":"i_ts_pump","source":{"sheet":"MBBR Issues","row":145}},
      {"id":"f_fix_ts_pump_15","name":"Fix: Effect of breakdown: sludge builds up in the tube settler and overflows if the pump stays down.","kind":"action","forTypes":["Pump","Submersible Pump","Tube settler"],"forStage":null,"use":"fix","version":1,"status":"published","steps":[{"id":1,"type":"instruction","text":"Meanwhile, desludge by gravity through the drain valve or a portable pump, reduce inflow if the blanket keeps rising, and monitor sludge blanket depth every shift.","link":{"kind":"task","id":"t_mb_desludge"}}],"cause":"c_ts_pump_15","issue":"i_ts_pump","source":{"sheet":"MBBR Issues","row":146}}
